INSERT INTO "entity_schemas" ("kind", "department", "fields") VALUES ('expenses', 'Finance', '[{"key":"name","type":"text","label":"รายการค่าใช้จ่าย","required":true},{"key":"projectId","type":"relation","label":"โครงการ","required":false,"resource":"projects"},{"key":"category","type":"select","label":"หมวดหมู่","picker":"expenseCategory","options":["ส่งเสริมการขาย","รับรอง/เลี้ยงลูกค้า","ค่าเดินทางและที่พัก","ค่าน้ำมัน/แก๊ส/รถยนต์","ค่าขนส่งลูกค้า/ลอจิสติกส์","ค่าเช่า","เงินมัดจำ/ประกัน","เบี้ยประกัน","ค่าธรรมเนียมธนาคาร","ภาษีและทะเบียน","ซื้อสินค้าไว้ขาย","ซื้อของ/วัสดุไว้ให้บริการ","สินค้าตัวอย่าง/ของแจกแถม","คอมพิวเตอร์/อุปกรณ์ไอที","เฟอร์นิเจอร์/อุปกรณ์สำนักงาน","เฟอร์นิเจอร์และตกแต่งสำนักงาน","ยานพาหนะ","ซอฟท์แวร์คอมพิวเตอร์","ค่าส่งเอกสาร/เมสเซนเจอร์/ไปรษณีย์","โปรแกรม/ซอฟท์แวร์/แอพลิเคชั่น","วัสดุสำนักงาน/เครื่องเขียน","ค่าเช่าออฟฟิศ","โทรศัพท์","ค่าไฟ","อินเตอร์เน็ต","ค่าน้ำ","บริการทั่วไป/ฟรีแลนซ์","บริการด้านบัญชี","เงินเดือน/ค่าจ้าง","เบี้ยเลี้ยง","ประกันสังคม","สวัสดิการพนักงาน","ค่าล่วงเวลา","ค่าคอมมิชชั่นพนักงานขาย","ส่วนตัว","ค่านายหน้าและส่วนแบ่งการขาย","ซ่อมแซมบำรุงรักษา","ดอกเบี้ยเงินกู้ยืม","ค่าใช้จ่ายทั่วไป","ค่ามัดจำ","ค่าไฟฟ้า","ค่าบริการ","ค่าพรม","บุคลากร","จัดซื้อ","ขนส่ง","การตลาด","อื่นๆ"],"required":true},{"key":"accountCode","type":"text","label":"รหัสผังบัญชี","required":false},{"key":"costCenter","type":"text","label":"ศูนย์ต้นทุน","required":false},{"key":"payee","type":"text","label":"ผู้รับเงิน","required":false},{"key":"supplierId","type":"relation","label":"Supplier","required":false,"resource":"suppliers"},{"key":"docType","type":"select","label":"ประเภทเอกสาร","options":["ใบกำกับภาษีเต็มรูป","ใบกำกับภาษีอย่างย่อ","ใบเสร็จ","ใบแจ้งหนี้"],"required":false},{"key":"docNo","type":"text","label":"เลขที่เอกสาร","required":false},{"key":"taxId","type":"text","label":"เลขผู้เสียภาษีผู้ขาย","required":false},{"key":"date","type":"date","label":"วันที่","required":true},{"key":"receiptId","type":"image","label":"ไฟล์ใบเสร็จ","hidden":t